/**
 * Baked georeferences (F1 frame → WGS84) for the 3D map, one per baked
 * circuit geometry file. Generated by `node scripts/fetch-georef.mjs`.
 *
 * Import only from the lazily-loaded 3D map chunk.
 */
import type { CircuitGeoref } from "@/utils/georef";
import { resolveGeometryYear } from "./circuitGeometry";
import baked from "./circuit-georef.json";

const CIRCUITS = baked.circuits as Record<string, CircuitGeoref>;

/** Georef matching the geometry file `useCircuitGeometry` resolves, or null. */
export function getCircuitGeoref(
  circuitKey: number | null | undefined,
  year?: number | null,
): CircuitGeoref | null {
  if (circuitKey == null) return null;
  const resolved = resolveGeometryYear(circuitKey, year);
  if (resolved === null) return null;
  return CIRCUITS[`${circuitKey}-${resolved}`] ?? null;
}
